import CategoryProductBrowser from "@/components/category/CategoryProductBrowser";
import fallbackProducts from "@/data/products.json";
import type { Product } from "@/types/product";
import { notFound } from "next/navigation";

const API_BASE_URL = process.env.LARAVEL_API_URL ?? "http://127.0.0.1:8000/api";

async function getProducts(): Promise<Product[]> {
  try {
    const response = await fetch(`${API_BASE_URL}/products`, {
      cache: "no-store",
      headers: { Accept: "application/json" },
    });

    if (!response.ok) throw new Error("Không tải được sản phẩm.");

    return await response.json();
  } catch {
    return fallbackProducts as Product[];
  }
}

export default async function CategoryPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const categoryMap: Record<string, string> = {
    "mat-kinh": "Mắt kính",
    "gong-kinh": "Gọng kính",
    "phu-kien": "Phụ kiện",
  };
  const categoryName = categoryMap[slug];

  if (!categoryName) {
    notFound();
  }

  const products = await getProducts();
  const categoryProducts = products.filter((product) => product.category === categoryName);

  return (
    <div className="bg-background min-h-[calc(100vh-160px)] py-12 lg:py-16">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8 max-w-7xl">
        <div className="mb-8 border-b border-border pb-4 flex justify-between items-end">
          <div>
            <h1 className="text-3xl font-bold text-foreground capitalize">
              Danh mục: <span className="text-primary">{categoryName}</span>
            </h1>
            <p className="text-muted-foreground mt-2">
              Có {categoryProducts.length} sản phẩm
            </p>
          </div>
        </div>

        <CategoryProductBrowser products={categoryProducts} categoryName={categoryName} />
      </div>
    </div>
  );
}
